/**
 * @summary List comments for a report
 */
export const getListCommentsUrl = (
  reportId: string,
  params?: ListCommentsParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/comments/${reportId}?${stringifiedParams}`
    : `/api/comments/${reportId}`;
};

export const listComments = async (
  reportId: string,
  params?: ListCommentsParams,
  options?: RequestInit,
): Promise<CommentsResponse> => {
  return customFetch<CommentsResponse>(getListCommentsUrl(reportId, params), {
    ...options,
    method: "GET",
  });
};

export const getListCommentsQueryKey = (
  reportId: string,
  params?: ListCommentsParams,
) => {
  return [`/api/comments/${reportId}`, ...(params ? [params] : [])] as const;
};

export const getListCommentsQueryOptions = <
  TData = Awaited<ReturnType<typeof listComments>>,
  TError = ErrorType<unknown>,
>(
  reportId: string,
  params?: ListCommentsParams,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof listComments>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey =
    queryOptions?.queryKey ?? getListCommentsQueryKey(reportId, params);

  const queryFn: QueryFunction<Awaited<ReturnType<typeof listComments>>> = ({
    signal,
  }) => listComments(reportId, params, { signal, ...requestOptions });

  return {
    queryKey,
    queryFn,
    enabled: !!reportId,
    ...queryOptions,
  } as UseQueryOptions<
    Awaited<ReturnType<typeof listComments>>,
    TError,
    TData
  > & { queryKey: QueryKey };
};

export type ListCommentsQueryResult = NonNullable<
  Awaited<ReturnType<typeof listComments>>
>;
export type ListCommentsQueryError = ErrorType<unknown>;

/**
 * @summary List comments for a report
 */

export function useListComments<
  TData = Awaited<ReturnType<typeof listComments>>,
  TError = ErrorType<unknown>,
>(
  reportId: string,
  params?: ListCommentsParams,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof listComments>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
): UseQueryResult<TData, TError> & { queryKey: QueryKey } {
  const queryOptions = getListCommentsQueryOptions(reportId, params, options);

  const query = useQuery(queryOptions) as UseQueryResult<TData, TError> & {
    queryKey: QueryKey;
  };

  return { ...query, queryKey: queryOptions.queryKey };
}

